/* Review-only flows: named spirit instances, assignment previews and mock store receipts. */
const VentureShopUI=(()=>{
    const V=MageVentureSpirits,S=MageShop,scenes=['ventures','ventureMine','ventureRefinery','ventureSanctuary','ventureUpgrades','ventureAdvanced','inventory','traits','relics','consumables','bulkLoot','shop','chestCommon','chestUncommon','chestRare','chestEpic','chestLegendary','loot','giftsClaimed','lootOverflow','return','idle','map','monsters','tier2','spirits','drop'];
    const labels={ventureMine:'Gruvan · Produktion',ventureRefinery:'Gruvan · Refinery',ventureSanctuary:'Dammen · Sanctuary',ventureUpgrades:'Permanenta förbättringar',ventures:'Ventures · Nya resurser & egna mekaniker',ventureAdvanced:'Ventures · Djupare gruva & nya livsmiljöer',inventory:'Inventory · Staplar & mängdval',traits:'Permanenta traits · Idle / Active',relics:'Relikkistor · Öppna i mängd',consumables:'Scrolls · Förhandsvisa effekten',bulkLoot:'Pickup · Hämta alla',chestCommon:'Kista · Common',chestUncommon:'Kista · Uncommon',chestRare:'Kista · Rare',chestEpic:'Kista · Epic',chestLegendary:'Kista · Legendary',loot:'Idle · Föremålsfynd',giftsClaimed:'Daglig kista · Hämtad',lootOverflow:'Många fynd · Säkert förvar',return:'Frånvaro · Föremål väntar',idle:'Idle · Direkta spell-slots',map:'B · Fyra bossportar',monsters:'Monster · Obsidian Reach',tier2:'Tier 2 · Magma Basilisk',spirits:'Ventures · Tilldelade spirits',drop:'Nytt fynd · Echo Wisp',shop:'Butik · Kosmetik & bekvämlighet'};
    let review='idle',page=0,search='',serial=0,accountReceipts=[];
    const reviewEnabled=()=>new URLSearchParams(location.search).has('experience');
    const rates=data=>V.production(state,data||state.ventureSpirits);
    const number=n=>Number(n.toFixed(1)).toLocaleString('en');
    const ventureName=id=>id==='mine'?'Moonstone mine':id==='pond'?'Silverfin pond':'Unassigned';
    const entry=id=>state.ventureSpirits.owned.find(s=>s.id===id);
    const assigned=id=>state.ventureSpirits.owned.filter(s=>s.assigned===id);
    const label=()=>labels[review];
    function ventures(){return VentureDevelopmentUI.overview();}
    function spirits(){const filter=state.spiritFilter||'All',all=state.ventureSpirits.owned,items=all.filter(s=>(filter==='All'||filter==='Unassigned'&&!s.assigned||filter.startsWith('For ')&&V.find(s.kind).ventures.includes(filter.slice(4))||s.assigned===filter)&&V.find(s.kind).name.toLowerCase().includes(search)),pages=Math.max(1,Math.ceil(items.length/12));page=Math.min(page,pages-1);return `<section class="page spirits-page"><div class="compact-heading">${title('Spirits')}<button class="text-button" data-view="ventures">${sprite('mine')} Ventures ›</button></div><div class="collection-tools"><input data-spirit-search aria-label="Search spirits" placeholder="Search spirits…" value="${esc(search)}"><select data-spirit-filter aria-label="Filter spirits">${[['All','All'],['Unassigned','Unassigned'],['mine','Mine'],['pond','Pond'],['For mine','Mine compatible'],['For pond','Pond compatible']].map(([id,name])=>`<option value="${id}" ${id===filter?'selected':''}>${name}</option>`).join('')}</select></div><div class="collection-meta">${items.length} / ${all.length} spirits</div><div class="collection-grid spirit-grid">${items.slice(page*12,(page+1)*12).map(s=>{const d=V.find(s.kind);return `<button class="collection-card spirit-card ${s.assigned?'selected':''}" style="--spirit-color:${d.rarity==='Epic'?'#b69aef':'#72c6ee'}" data-spirit="${s.id}" aria-label="${d.name}, ${d.rarity}, ${ventureName(s.assigned)}. Assign spirit">${sprite(d.art)}<strong>${d.name}</strong><small class="spirit-rarity">${d.rarity}</small><span class="spirit-station">${s.assigned?sprite(s.assigned):'<i aria-hidden="true">+</i>'}${s.assigned?(s.assigned==='mine'?'Mine':'Pond'):'Assign'}</span></button>`;}).join('')}</div>${!items.length?'<p class="no-results">No spirits here yet.</p>':''}${pages>1?`<div class="pagination"><button data-spirit-page="-1" aria-label="Previous spirits" ${page===0?'disabled':''}>←</button><span>${page+1} / ${pages}</span><button data-spirit-page="1" aria-label="Next spirits" ${page===pages-1?'disabled':''}>→</button></div>`:''}<p class="collection-footnote">${sprite('spirit')} Base spirits keep working. Assigned loot spirits stack.</p></section>`;}
    function productionInfo(id){const r=rates(),mine=id==='mine';return `<div class="venture-art">${sprite('venture-site-'+id)}${metric(mine?'ore':'pearls',number(mine?r.ore:r.pearls)+'/min','Total production per minute')}</div><div class="return-line"><span>Base spirits</span><b>${mine?state.mining:state.fishing}</b></div><div class="return-line"><span>Assigned loot spirits</span><b>${assigned(id).length}</b></div><div class="return-line"><span>Loot output (base equivalents)</span><b>+${mine?r.mineWorkers:r.pondWorkers}</b></div><div class="return-line"><span>Spirit production bonus</span><b>+${Math.round((mine?r.mineBonus:r.pondBonus)*100)}%</b></div>${mine?`<div class="return-line"><span>Pond synergy</span><b>×${state.synergy?'1.25':'1'}</b></div>`:`<div class="return-line"><span>Delver side finds</span><b>+${r.sidePearls} Pearls/min</b></div>`}<div class="return-line"><span>Sanctuary multiplier</span><b>×${number(MageVentureDevelopment.bonuses(state.ventureDevelopment)[id])}</b></div><p class="compact-notice">(Base + loot output) × (1 + bonuses)${mine?' × pond synergy':', plus side finds'} × sanctuary</p><button class="rune-button secondary" data-spirit-list="${id}">Manage spirits</button>`;}
    function shop(){return ShopGiftsUI.view();}
    function modal(m){if(m.type==='shopProduct'){const p=S.products.find(p=>p.id===m.product),owned=state.shop.owned.includes(p.id),equipped=state.shop.equipped===p.id;return {heading:p.name,body:`<div class="shop-detail-preview shop-mage-preview" data-cosmetic="${p.id}">${sprite('mage')}${p.id==='noAds'?ui('lock','ad-free-seal'):''}</div><p class="center">${p.description}</p><div class="return-line"><span>${p.type}</span><b>${owned?'Owned':p.price}</b></div><p class="compact-notice">${p.type==='Cosmetic'?'Appearance only · No stat changes':'One purchase · Restore on your account'}</p>${owned?(p.type==='Cosmetic'?`<button class="rune-button" data-shop-equip="${equipped?'none':p.id}">${equipped?'Unequip':'Equip'}</button>`:'<p class="shop-owned">✓ Ad-free unlocked</p>'):`<button class="rune-button" data-shop-buy="${p.id}">Demo purchase · ${p.price}</button><small class="shop-demo">No payment will be taken</small>`}`};}
        const s=entry(m.id),d=V.find(s.kind),drop=m.type==='spiritDrop',before=rates();return {heading:drop?'Spirit discovered':d.name,body:`<div class="spirit-detail-hero ${drop?'new-spirit':''}">${sprite(d.art)}<div><span class="spirit-rarity">${d.rarity} · Loot spirit</span><h3>${d.name}</h3><small>${drop?'Idle find':ventureName(s.assigned)}</small></div></div><div class="spirit-perks">${ui('power')}<strong>2× base output<br>${d.perk}</strong></div><div class="spirit-assignments">${d.ventures.map(v=>{const copy=structuredClone(state.ventureSpirits);V.assign(copy,s.id,v);const after=rates(copy),is=s.assigned===v;return `<button class="spirit-assignment ${is?'selected':''}" data-spirit-assign="${v}" data-spirit-id="${s.id}" ${is?'disabled':''} aria-label="Assign ${d.name} to ${ventureName(v)}">${sprite('venture-site-'+v)}<span><strong>${ventureName(v)}</strong><small>${ui(v==='mine'?'ore':'pearls','inline-icon')}${number(v==='mine'?before.ore:before.pearls)} → <b>${number(v==='mine'?after.ore:after.pearls)}/min</b>${after.ore!==before.ore&&v==='pond'?` · Mine ${number(before.ore)} → ${number(after.ore)}`:after.pearls!==before.pearls&&v==='mine'?` · Pearls ${number(before.pearls)} → ${number(after.pearls)}`:''}</small></span><b>${is?'✓':'+'}</b></button>`;}).join('')}</div>${s.assigned?`<button class="text-button" data-spirit-assign="none" data-spirit-id="${s.id}">Unassign spirit</button>`:''}<p class="spirit-safety">${ui('lock')} Base spirits stay. Each loot spirit works in one venture.</p>`};
    }
    function decorate(){phone.dataset.cosmetic=state.shop.equipped||'';}
    function scenario(key){review=scenes.includes(key)?key:'idle';RealmProgression.scenario(review==='tier2'?'tier2':review==='monsters'?'fireEnd':'route');state.idle=['Firebolt','Icebolt','Frostfire Cone','Fire Shield'];state.unlocked=[...new Set([...state.unlocked,...state.idle])];state.forgeLevel=3;state.boss=[...state.idle];page=0;search='';if(['ventures','ventureAdvanced','ventureMine','ventureRefinery','ventureSanctuary','ventureUpgrades'].includes(review)){VentureDevelopmentUI.seed(review!=='ventures');if(review==='ventureMine')VentureDevelopmentUI.open('mine');if(review==='ventureRefinery')VentureDevelopmentUI.open('mine','craft');if(review==='ventureSanctuary')VentureDevelopmentUI.open('pond','craft');if(review==='ventureUpgrades')VentureDevelopmentUI.open('pond','upgrades');}else if(['inventory','traits','relics','consumables','bulkLoot'].includes(review)){RelicInventoryUI.seed();if(review==='bulkLoot'){GroundLoot.seed(30);go('realm');}else if(review==='traits')go('character');else{go('inventory');if(review==='relics')RelicInventoryUI.openItem('relic-4');if(review==='consumables')RelicInventoryUI.openItem('time-10');}}else if(review==='map')openModal({type:'map'});else if(review==='spirits')go('ventures');else if(review==='shop')go('shop');else if(review.startsWith('chest')){go('shop');ShopGiftsUI.reviewClaim(['chestCommon','chestUncommon','chestRare','chestEpic','chestLegendary'].indexOf(review));}else if(review==='giftsClaimed'){const gift=MageFreeGifts.claim(state,{id:'review-gift',now:DungeonUI.clock(),sample:0});state.giftReceipt=gift.receipt;go('shop');}else if(review==='loot'||review==='lootOverflow'){GroundLoot.seed(review==='loot'?3:30);go('realm');}else if(review==='return'){window.scenario('return');}else if(review==='drop'){MageItemLoot.queue(state.groundLoot,{id:'echo-drop',kind:'spirit',key:'echo',realm:0,rarity:3,source:'review'});go('realm');}else go('realm');const u=new URL(location.href);u.searchParams.set('experience',review);u.searchParams.set('map','B');history.replaceState(null,'',u);render(true);}
    function handle(el){if(VentureDevelopmentUI.handle(el)||ShopGiftsUI.handle(el)||GroundLoot.handle(el))return true;if(el.dataset.experience){scenario(el.dataset.experience);return true;}if(el.dataset.spirit){openModal({type:'spirit',id:el.dataset.spirit});return true;}if(el.dataset.spiritList){state.spiritFilter='For '+el.dataset.spiritList;page=0;go('spirits');return true;}if(el.dataset.spiritAssign){const ok=V.assign(state.ventureSpirits,el.dataset.spiritId,el.dataset.spiritAssign==='none'?null:el.dataset.spiritAssign);if(ok){state.modal=null;notify(el.dataset.spiritAssign==='none'?'Spirit unassigned':'Spirit assigned');}return true;}if(el.dataset.spiritPage){page+=Number(el.dataset.spiritPage);render(true);return true;}if(el.dataset.shopProduct){openModal({type:'shopProduct',product:el.dataset.shopProduct});return true;}if(el.dataset.shopBuy){const receipt='demo-store-'+(++serial),id=el.dataset.shopBuy;if(S.purchase(state.shop,id,receipt)){accountReceipts.push({id,receipt});notify('Demo purchase complete');}return true;}if(el.dataset.shopEquip){S.equip(state.shop,el.dataset.shopEquip==='none'?null:el.dataset.shopEquip);state.modal=null;notify('Appearance updated');return true;}if(el.hasAttribute('data-shop-restore')){S.restore(state.shop,accountReceipts);notify(accountReceipts.length?'Purchases restored':'No purchases to restore');return true;}return false;}
    function change(delta){scenario(scenes[(scenes.indexOf(review)+delta+scenes.length)%scenes.length]);}
    function start(){document.addEventListener('input',e=>{if(e.target.hasAttribute('data-spirit-search')){search=e.target.value;page=0;const start=e.target.selectionStart;render(true);const input=phone.querySelector('[data-spirit-search]');input.focus();input.setSelectionRange(start,start);}});document.addEventListener('change',e=>{if(e.target.hasAttribute('data-spirit-filter')){state.spiritFilter=e.target.value;page=0;render(true);}});if(reviewEnabled())scenario(new URLSearchParams(location.search).get('experience'));}
    return {ventures,spirits,productionInfo,shop,modal,handle,reviewEnabled,change,label,start,decorate,scenario};
})();
